  'cv-0281': [['Oh, I hate', 'when I do that.', 'What about the kids?'], ['아, 정말 싫어', '내가 그럴 때면.', '아이들은 어떡했어?']],
  'cv-0282': [['I somehow managed', 'to get the kids', 'to school', 'on time.'], ['나는 어찌어찌 해냈어', '아이들을 보내는 것을', '학교에', '제시간에.']],
